3	/**
4	 * Tiny, dependency-free i18n helper. English-only for now, but the app reads
5	 * every user-facing string through `t()` so the catalog can be swapped or
6	 * extended later (see CLAUDE.md rule 7). No hard-coded UI strings in components.
7	 */
8	
9	type Messages = typeof en;
10	
11	/** Dotted key paths into the message catalog, e.g. "auth.signInTitle". */
12	type DottedKeys<T, Prefix extends string = ""> = {
13	  [K in keyof T & string]: T[K] extends string
14	    ? `${Prefix}${K}`
15	    : DottedKeys<T[K], `${Prefix}${K}.`>;
16	}[keyof T & string];
17	
18	export type MessageKey = DottedKeys<Messages>;
19	
20	function lookup(key: string): string | undefined {
21	  return key
22	    .split(".")
23	    .reduce<unknown>(
24	      (acc, part) =>
25	        acc && typeof acc === "object"
26	          ? (acc as Record<string, unknown>)[part]
27	          : undefined,
28	      en,
29	    ) as string | undefined;
30	}
31	
32	/**
33	 * Resolve a message by key, with optional `{name}`-style interpolation.
34	 * Returns the key itself if missing so a gap is visible rather than silent.
35	 */
36	export function t(
37	  key: MessageKey,
38	  vars?: Record<string, string | number>,
39	): string {
40	  const raw = lookup(key);
41	  if (typeof raw !== "string") {
42	    if (process.env.NODE_ENV !== "production") {
43	      console.warn(`[i18n] missing message for key: ${key}`);
44	    }
45	    return key;
46	  }
47	  if (!vars) return raw;
48	  return raw.replace(/\{(\w+)\}/g, (match, name: string) =>
49	    name in vars ? String(vars[name]) : match,
50	  );
51	}
